const getKeyValue = (obj, key) => obj[key];
export const pick = (propertyArray, object) => {
    if (object instanceof Object) {
        return propertyArray.reduce((acc, curr) => ({
            ...acc,
            [curr]: getKeyValue(object, curr),
        }), {});
    }
    throw Error('The value for argument "object" must be an object');
};
export const orderByDescending = (property) => {
    return (a, b) => {
        if (a[property] > b[property])
            return -1;
        if (a[property] < b[property])
            return 1;
        return 0;
    };
};
export const orderByAscending = (property) => {
    return (a, b) => {
        if (a[property] < b[property])
            return -1;
        if (a[property] > b[property])
            return 1;
        return 0;
    };
};
